insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('coins-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Coins', 'A play-based activity for strengthening classification and categorisation.', 8, '5–10 min', 'Real coins', 'Identify coins by appearance and name their values. Sorting coins by value -- not yet purchasing, just denominations.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('living-things-need-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Living Things Need...', 'A hands-on challenge that builds problem-solving and planning.', 8, '5–10 min', 'Plant to observe', 'What do plants need? What do animals need?'' Beginning biology -- organisms have requirements for survival.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('simple-map-reading-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Simple Map Reading', 'A hands-on challenge that builds spatial reasoning and problem-solving.', 13, '10–15 min', 'Drawn map + hidden object', 'A map of the house or garden. Find a ''treasure'' hidden using map coordinates. Spatial representation reading.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('manage-waiting-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Manage Waiting', 'A play-based activity for strengthening sharing, fairness and turn-taking.', 8, '5–10 min', 'Timer', 'Wait 5 minutes for something desirable with a visible timer. Narrate the wait: ''We''re waiting. That is hard. We can do it.''', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('what-you-need-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'What You Need', 'A hands-on challenge that builds social skills and emotional understanding.', null, 'Ongoing', 'None', 'Practice saying ''I need...'' or ''Can I have...'' instead of grabbing, whining, or melting down. Verbal request habit.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('others-feelings-first-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Others'' Feelings First', 'An activity that develops emotional regulation and vocabulary.', null, 'Ongoing', 'None', 'Before I say what I want, let me notice how you are feeling.'' Other-first awareness is sophisticated SE development.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('resilience-story-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Resilience Story', 'A play-based activity for strengthening social skills and emotional understanding.', 8, '5–10 min', 'Book with resilience theme', 'Read a book about a character who faces difficulty and succeeds. Discuss: ''What did they do when it was hard?''', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('disagree-respectfully-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Disagree Respectfully', 'A hands-on challenge that builds conflict resolution.', null, 'Ongoing', 'None', 'I think it''s different because...'' Teaching disagreement that doesn''t damage the relationship.', 'Children this age can begin to name feelings and see another point of view, with support. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('gratitude-letter-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Gratitude Letter', 'A play-based activity for strengthening empathy and perspective-taking.', 8, '5–10 min', 'Paper and pencil', 'Dictate a thank-you to someone who helped them. Gratitude expressed externally = prosocial behaviour building.', 'Children this age can begin to name feelings and see another point of view, with support. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('cooking-science-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Cooking Science', 'A hands-on challenge that builds sensory discrimination and integration.', 13, '10–15 min', 'Baking soda, vinegar, container', 'Mix baking soda and vinegar in a bowl. Watch, discuss why it fizzes. Hypothesis before result -- early science thinking.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('blindfold-smell-test-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Blindfold Smell Test', 'A hands-on challenge that builds smell and taste discrimination.', 8, '5–10 min', '6 strongly scented household items', 'Blindfolded: smell 6 household items and name them. Olfactory discrimination is rarely directly exercised.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('shadow-puppets-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Shadow Puppets', 'A play-based activity for strengthening sensory discrimination and integration.', 13, '10–15 min', 'Torch', 'Make hand-shadow animals on a wall with a torch. Visual creation + fine motor + narrative.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('rhythm-pattern-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Rhythm Pattern', 'An activity that develops auditory discrimination.', 7, '5–8 min', 'None', 'Clap a 4-beat pattern and ask child to copy. Then let them create one for you to copy. Rhythmic working memory.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('plant-observation-journal-y3_6', 'cognitive'::domain, 'y3_6'::age_band, 'Plant Observation Journal', 'An activity that develops sensory discrimination and integration.', 8, '5–10 min', 'Seed, pot, soil, drawing journal', 'Plant a seed and draw it each week. Observation + recording + science concept of growth over time.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('own-school-bag-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Own School Bag', 'A play-based activity for strengthening organising own belongings.', 8, '5–10 min', 'School bag + checklist', 'Child packs their own bag with a checklist: water bottle, lunch, library book, uniform. Executive function daily practice.', 'Children this age are far more capable than they are usually allowed to be, and real responsibility builds real confidence. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('manage-belongings-y3_6', 'social_emotional'::domain, 'y3_6'::age_band, 'Manage Belongings', 'A hands-on challenge that builds dressing independence.', null, 'Ongoing', 'None', 'Your responsibility: water bottle goes in your bag, shoes go in the rack, toys go in the box.'' Ownership of own items.', 'Children this age are far more capable than they are usually allowed to be, and real responsibility builds real confidence. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('skip-relay-race-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Skip Relay Race', 'An activity that develops jumping, hopping and skipping.', 13, '10–15 min', 'Small objects', 'Skip to a point, pick up an object, skip back -- in competition with self (timer) or family. Speed + skill combined.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('stand-tiptoes-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Stand Tiptoes', 'An activity that develops balance and postural control.', 4, '3–5 min', 'None', 'Balance on tiptoes for 10 seconds. Calf strength + balance + body awareness.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('throw-overhand-i-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Throw Overhand I', 'An activity that develops throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Ball + target', 'Overhand throw at a target 3 m away. Accuracy + distance combined = complex motor planning.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('balance-wobble-board-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Balance Wobble Board', 'A play-based activity for strengthening balance and postural control.', 8, '5–10 min', 'Cushion or improvised wobble surface', 'Any improvised wobble surface (cushion on board). Dynamic balance is harder than static balance.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('walk-hands-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Walk Hands', 'An activity that develops coordination and physical confidence.', 4, '3–5 min', 'None', 'Parent holds legs; child walks on hands. Shoulder girdle strength and weight-bearing through arms.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('stair-running-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Stair Running', 'A hands-on challenge that builds running and agility.', 7, '5–8 min', 'Stairs', 'With you close by, run up and down stairs at a safe, controlled pace. Requires much faster motor planning and leg activation than walking on stairs.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('dribble-around-obstacles-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Dribble Around Obstacles', 'A play-based activity for strengthening kicking and foot control.', 8, '5–10 min', 'Ball + obstacles', 'Dribble a ball around objects placed at 50-cm intervals. Controlled directional dribbling.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('landing-from-jump-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Landing from Jump', 'A hands-on challenge that builds jumping, hopping and skipping.', 4, '3–5 min', 'Low step or table', 'Jump from 40 cm and land softly -- bent knees, arms out. Controlled landing is as important as the jump itself.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('letter-formation-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Letter Formation', 'A hands-on challenge that builds pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters F, G, H, I, J. Focus on correct starting point and direction.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('sewing-running-stitch-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Sewing Running Stitch', 'A play-based activity for strengthening threading and precision.', 18, '15–20 min', 'Blunt needle, thread, open fabric', 'With an adult supervising closely, make a running stitch on open-weave fabric with a large blunt needle. Threading + in-out pattern + sustained fine motor.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('origami-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Origami', 'An activity that develops precision folding.', 13, '10–15 min', 'Square paper', 'Simple origami: bird or boat using 3-4 folds. Spatial + fine motor + following sequence.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('tying-knot-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Tying Knot', 'An activity that develops fastening and dressing skills.', 8, '5–10 min', 'Rope or shoelace', 'Tie an overhand knot in a rope. Pre-cursor to shoe-tying. Loop and through.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('scene-from-imagination-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Scene from Imagination', 'A play-based activity for strengthening drawing control and shape copying.', 13, '10–15 min', 'Drawing materials', 'Draw something that has never existed.'' Imagination into representation -- no reference, only internal image.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('model-from-plan-y3_9', 'motor'::domain, 'y3_9'::age_band, 'Model from Plan', 'An activity that develops drawing control and shape copying.', 13, '10–15 min', 'Blocks + reference picture', 'Look at a photo or drawing of a structure and recreate it with blocks. 2D-to-3D translation.', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('read-short-book-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Read Short Book', 'A play-based activity for strengthening early literacy.', 13, '10–15 min', 'Level-appropriate early reader', 'Level-appropriate early reader: 8-12 pages, 1-2 sentences per page. Independent reading attempt.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-short-sentence-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Write Short Sentence', 'A play-based activity for strengthening vocabulary and description.', 8, '5–10 min', 'Pencil and paper', '3-5 words, own spelling attempt. ''The cat is big.'' Phonetic spelling -- celebrate all attempts regardless of accuracy.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('explain-thinking-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Explain Thinking', 'A play-based activity for strengthening reasoning through language.', 8, '5–10 min', 'None', 'How did you know it was a dog? What told you?'' Metacognitive language: explaining reasoning, not just answering.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('presentation-family-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Presentation Family', 'An activity that develops expressive and receptive language.', 8, '5–10 min', 'Chosen object', 'Show-and-tell: choose an object and speak about it for 1 minute to family. Public speaking practice in a safe context.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('interview-family-member-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Interview Family Member', 'A hands-on challenge that builds expressive and receptive language.', 8, '5–10 min', 'None', 'Child interviews a parent or grandparent: ''What was your favourite food as a child?'' Language + social + inquiry.', 'This builds the language your child will use to reason, explain and eventually read. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('understand-idioms-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Understand Idioms', 'A hands-on challenge that builds expressive and receptive language.', 7, '5–8 min', 'None', 'It''s raining cats and dogs -- does that mean real cats and dogs?'' Figurative language awareness beginning.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('create-own-book-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Create Own Book', 'A hands-on challenge that builds narrative skills and retelling.', 18, '15–20 min', 'Paper, stapler, drawing materials', 'Fold 4 sheets of paper, staple, write a title, draw 4 pictures, dictate the story text. Author identity building.', 'This builds the language your child will use to reason, explain and eventually read. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('debate-evidence-y3_9', 'communication'::domain, 'y3_9'::age_band, 'Debate Evidence', 'An activity that develops reasoning through language.', 8, '5–10 min', 'None', 'Why do you think that? What makes you sure?'' Adding evidence to an opinion. Critical thinking through language.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('addition-subtraction-20-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Addition Subtraction 20', 'A hands-on challenge that builds number sense and early maths.', 8, '5–10 min', '20 objects + number line drawn on paper', 'Extend arithmetic to 20 with concrete supports first. Count-on strategy: start from the larger number.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('halves-quarters-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Halves Quarters', 'An activity that develops reasoning and problem-solving.', 8, '5–10 min', 'Apple or paper', 'Cut an apple or paper into 2 equal halves, then 4 equal quarters. Fraction concept through direct physical splitting.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('weight-comparison-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Weight Comparison', 'An activity that develops problem-solving and planning.', 8, '5–10 min', 'Plank, pivot (rolled towel), objects', 'Balance two objects on a plank over a pivot. Which is heavier? Direct comparison before scales.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('concept-time-duration-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Concept Time Duration', 'An activity that develops understanding time.', 7, '5–8 min', 'Timer', 'How long is 1 minute? 5 minutes? Time a minute of activity, then wait a minute. Duration concept before clock reading.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('animal-classification-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Animal Classification', 'An activity that develops classification and categorisation.', 8, '5–10 min', 'Toy animals or pictures', 'Sort animals into mammals, birds, fish, insects. Classification by shared characteristics = taxonomy thinking.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('create-survey-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Create Survey', 'An activity that develops reasoning and problem-solving.', 13, '10–15 min', 'Paper for tally chart', 'Do you prefer apples or oranges?'' Survey 5 family members, record results, draw graph. Data collection at its simplest.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('handle-unfairness-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Handle Unfairness', 'An activity that develops sharing, fairness and turn-taking.', 8, '5–10 min', 'None', 'When something seems unfair: ''Tell me what you think happened and what you think would be fair.'' Reasoning about justice.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('include-outsider-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Include Outsider', 'A play-based activity for strengthening social skills and emotional understanding.', null, 'Ongoing', 'None', 'When playing with others: ''Is there anyone who isn''t playing? Can we include them?'' Proactive inclusivity.', 'Children this age can begin to name feelings and see another point of view, with support. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('persistence-practice-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Persistence Practice', 'A hands-on challenge that builds social skills and emotional understanding.', 8, '5–10 min', 'Challenging task', 'Attempt something just beyond current ability for 5 minutes without giving up. ''I can''t do it yet -- not yet.''', 'Children this age can begin to name feelings and see another point of view, with support. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('manage-boredom-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Manage Boredom', 'A hands-on challenge that builds social skills and emotional understanding.', 8, '5–10 min', '5 household objects', 'I''m bored.'' Response: ''Let''s see what you can create with these 5 things.'' Resourcefulness from boredom = creativity.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('recognise-own-triggers-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Recognise Own Triggers', 'A hands-on challenge that builds empathy and perspective-taking.', 8, '5–10 min', 'None', 'What kinds of things make you feel very upset? Let''s make a list.'' Trigger awareness before trigger management.', 'Children this age can begin to name feelings and see another point of view, with support. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('celebrate-failure-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Celebrate Failure', 'A hands-on challenge that builds sharing, fairness and turn-taking.', 8, '5–10 min', 'None', 'Share a time you failed and what you learned. Normalise failure explicitly: ''Failing is how we find out what to do differently.''', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('garden-science-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Garden Science', 'A hands-on challenge that builds water play and sensory exploration.', null, 'Ongoing', 'Seeds, pot, soil, water', 'Plant seeds, water them, observe growth daily. Science hypothesis: ''What does a plant need to grow?''', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('colour-mixing-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Colour Mixing', 'An activity that develops sensory discrimination and integration.', 13, '10–15 min', 'Red, blue, yellow paint; paper', 'Primary colour mixing: what does red + blue make? Let child predict before mixing. Science + sensory + language.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('build-marble-run-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Build Marble Run', 'An activity that develops sensory discrimination and integration.', 18, '15–20 min', 'Paper tubes, tape', 'Build a run from rolled paper or tubes. Engineering: ramp angle, connections, energy transfer.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('listen-classical-music-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Listen Classical Music', 'A play-based activity for strengthening auditory discrimination.', 8, '5–10 min', 'Classical music recording', 'Sit for 5 minutes and listen to a piece of music without words. What pictures does it make in your mind?', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('clay-pottery-y3_9', 'cognitive'::domain, 'y3_9'::age_band, 'Clay Pottery', 'An activity that develops tactile discrimination.', 18, '15–20 min', 'Clay or atta dough', 'Roll long clay coils and stack them to build a pot. Coil pottery is one of the oldest craft techniques.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('responsible-pet-care-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Responsible Pet Care', 'A hands-on challenge that builds independent eating and serving.', 8, '5–10 min', 'Pet-care materials', 'If family has a pet: feed, water, clean up after under supervision. Daily animal responsibility.', 'Doing things for themselves builds the planning and sequencing skills that also support learning. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('money-small-purchase-y3_9', 'social_emotional'::domain, 'y3_9'::age_band, 'Money Small Purchase', 'A play-based activity for strengthening everyday independence.', 8, '5–10 min', 'Coins', 'Give coins for a small purchase at a shop. Count out the right amount. Real-world transaction practice.', 'Children this age are far more capable than they are usually allowed to be, and real responsibility builds real confidence. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('metres-without-stopping-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Metres Without Stopping', 'A play-based activity for strengthening jumping, hopping and skipping.', 7, '5–8 min', 'Open space', 'Sustained skipping over a distance requires stamina as well as skill -- the motor pattern becomes automatic.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('ride-bicycle-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Ride Bicycle', 'A play-based activity for strengthening balance and postural control.', 18, '15–20 min', 'Bicycle with training wheels', 'Balance + steering + pedalling + braking all together. Even with training wheels, this is the most complex motor task to date.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('non-dominant-foot-i-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Non-Dominant Foot I', 'A hands-on challenge that builds jumping, hopping and skipping.', 4, '3–5 min', 'None', '5+ hops on the non-dominant foot. This typically lags dominant by 3-6 months -- both sides need direct practice.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('throw-distance-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Throw Distance', 'A play-based activity for strengthening throwing, catching and hand-eye coordination.', 8, '5–10 min', 'Ball', 'Overhand throw to 5-metre distance. Full body rotation, arm extension, and follow-through must all coordinate.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('from-50-cm-y4_0', 'motor'::domain, 'y4_0'::age_band, 'from 50 cm', 'An activity that develops jumping, hopping and skipping.', 4, '3–5 min', 'Step or table (50 cm)', 'Jump from a 50-cm height and land safely with soft knees. Height judgement and controlled landing.', 'This builds coordination and control at exactly the point where a child can start to see their own improvement. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('move-music-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Move Music', 'An activity that develops rhythm and coordinated movement.', 8, '5–10 min', 'Music with varied rhythm', 'Move to music with syncopated rhythm. Following complex rhythm requires auditory discrimination and motor response.', 'Physical confidence is being set now, and children who feel capable in their bodies at this age tend to stay active later. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('aim-kick-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Aim Kick', 'An activity that develops kicking and foot control.', 8, '5–10 min', 'Ball', 'Kick a rolling ball -- timing the contact point on a moving target.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('side-shuffle-race-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Side Shuffle Race', 'An activity that develops coordination and physical confidence.', 7, '5–8 min', 'None', 'Side-shuffle (step-together-step) to a point and back. Lateral movement at speed.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('letter-formation-i-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Letter Formation I', 'An activity that develops pre-writing and letter formation.', 8, '5–10 min', 'Pencil and paper', 'Correct formation of letters K, L, M, N, O, P. Build toward writing the full alphabet.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('draw-portrait-person-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Draw Portrait Person', 'A play-based activity for strengthening drawing control and shape copying.', 13, '10–15 min', 'Drawing materials', 'Draw a person with face details: eyes, nose, mouth, hair, eyebrows. Observed portrait vs schematic figure.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('knit-or-crochet-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Knit or Crochet', 'A hands-on challenge that builds fine motor precision.', 18, '15–20 min', 'Thick yarn and large needles', 'Knitting: cast on 8 stitches, do 4 rows. Even basic knitting requires bilateral coordination and pattern following.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('cut-complex-shape-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Cut Complex Shape', 'A hands-on challenge that builds drawing control and shape copying.', 13, '10–15 min', 'Child scissors and paper with complex outline', 'Cut out a picture of a house or animal from a drawn outline. Complex shape-following.', 'Children need strong, controlled hands before letter formation makes sense, and this builds exactly that. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('freestanding-tall-tower-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Freestanding Tall Tower', 'A play-based activity for strengthening construction and spatial precision.', 13, '10–15 min', 'Cardboard boxes, toilet rolls, tape', 'Build the tallest possible tower from household recycling. Stability physics: base width vs height ratio.', 'This develops the hand strength and control that writing will demand, well before formal writing begins. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('construct-paper-aeroplane-y4_0', 'motor'::domain, 'y4_0'::age_band, 'Construct Paper Aeroplane', 'An activity that develops construction and spatial precision.', 13, '10–15 min', 'Paper', 'Basic paper plane requires 5-6 precise folds. Launch it: does direction of fold affect flight?', 'Precision at this age comes from doing things with the hands repeatedly, not from being taught how. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Fine Motor Development; Handwriting Without Tears readiness framework; IAP'),
  ('level-1-early-reader-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Level-1 Early Reader', 'A hands-on challenge that builds early literacy.', 13, '10–15 min', 'Level 1 early reader book', '8-12 pages, repeating sentence pattern. Read independently; parent supports only when stuck.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-own-story-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Write Own Story', 'A hands-on challenge that builds narrative skills and retelling.', 13, '10–15 min', 'Pencil and paper', '3 sentences: character, problem, resolution. Own invented narrative committed to paper.', 'Vocabulary at this age is one of the strongest predictors of later reading, and it grows through talk and stories. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('20-sight-words-y4_0', 'communication'::domain, 'y4_0'::age_band, '20 Sight Words', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'Sight word cards', 'First 20 high-frequency words. These are the building blocks of early reading fluency.', 'This builds the language your child will use to reason, explain and eventually read. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('simile-introduction-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Simile Introduction', 'An activity that develops expressive and receptive language.', 8, '5–10 min', 'None', 'The cloud is like cotton wool.'' Make 5 similes about things in the room. Figurative language production.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('story-different-ending-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Story Different Ending', 'A play-based activity for strengthening narrative skills and retelling.', 8, '5–10 min', 'Familiar story', 'After reading a story, ask: ''What would happen if the ending was different?'' Narrative manipulation.', 'This builds the language your child will use to reason, explain and eventually read. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('listen-draw-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Listen Draw', 'A hands-on challenge that builds vocabulary and description.', 8, '5–10 min', 'Drawing materials', 'Describe a scene verbally; child draws it without seeing the description. Listening comprehension + visual production.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('read-simple-poem-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Read Simple Poem', 'An activity that develops phonological awareness.', 8, '5–10 min', 'Simple poem', 'Read a short poem together. Identify rhymes, count syllables in words. Poetry as a linguistic object.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('write-letter-y4_0', 'communication'::domain, 'y4_0'::age_band, 'Write Letter', 'An activity that develops expressive and receptive language.', 13, '10–15 min', 'Pencil and paper', 'Dictate or write a letter to a real person (grandparent, friend). Letter-writing structure: greeting, body, sign-off.', 'Children this age learn language best through genuine conversation rather than through being quizzed. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'ASHA Speech and Language Milestones; NCERT Foundational Literacy and Numeracy; IAP'),
  ('addition-carrying-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Addition Carrying', 'A play-based activity for strengthening number sense and early maths.', 8, '5–10 min', 'Objects + tens and ones representation', '9 + 3 = 12. The concept that 10 ones become 1 ten. Use objects to cross the 10-barrier concretely.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('number-line-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Number Line', 'A hands-on challenge that builds number sense and early maths.', 8, '5–10 min', 'Paper', 'Draw a number line 0-20 and use it for addition and subtraction. The number line models quantity spatially.', 'Children this age learn concepts by handling them physically before they can handle them abstractly. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('measure-non-standard-units-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Measure Non-Standard Units', 'An activity that develops reasoning and problem-solving.', 8, '5–10 min', 'Paper for recording', 'Measure the table using hand-spans, or the room using shoe-lengths. Non-standard measurement before cm.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('plant-life-cycle-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Plant Life Cycle', 'A play-based activity for strengthening problem-solving and planning.', 8, '5–10 min', 'Paper and crayons', 'Seed → sprout → plant → flower → seed. Draw the cycle as a diagram. First cyclical thinking in science.', 'Thinking skills at this stage develop through exploration and questions rather than through being taught answers. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('force-motion-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Force Motion', 'An activity that develops prediction and early scientific thinking.', 8, '5–10 min', 'Toy car, different surfaces', 'Push a toy car on carpet vs smooth floor. Why is one harder? Forces changing motion -- first physics concept.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('3d-shape-names-y4_0', 'cognitive'::domain, 'y4_0'::age_band, '3D Shape Names', 'A hands-on challenge that builds spatial reasoning and problem-solving.', 8, '5–10 min', 'Household objects', 'Cube, sphere, cylinder, cone, pyramid. Match to household objects. 3D shape language before formal geometry.', 'This builds the reasoning and problem-solving that school will draw on, in a form your child can actually enjoy. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'Harvard Center on the Developing Child (Executive Function); NCERT Foundational Numeracy; IAP'),
  ('you-need-help-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'You Need Help', 'A hands-on challenge that builds emotional regulation and vocabulary.', null, 'Ongoing', 'None', 'This is too hard for me right now. I need support.'' Asking for help before frustration peaks is executive function.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('handle-being-wrong-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Handle Being Wrong', 'A hands-on challenge that builds confidence and willingness to try.', null, 'Ongoing', 'None', 'When corrected, respond: ''Oh, I see. So I was wrong about that -- I''ll try to remember.'' Model and practice.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('interest-another-s-world-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Interest Another''s World', 'A hands-on challenge that builds managing winning and losing.', 8, '5–10 min', 'None', 'What is your favourite thing? Tell me all about it.'' Genuine curiosity about another''s inner life -- theory of mind growing.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('disagree-politely-adult-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Disagree Politely Adult', 'A play-based activity for strengthening conflict resolution.', null, 'Ongoing', 'None', 'I think it might be a bit different because...'' Respectful disagreement with authority. Assertiveness, not defiance.', 'Children this age can begin to name feelings and see another point of view, with support. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('group-project-contribution-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Group Project Contribution', 'A hands-on challenge that builds friendship and cooperative play.', 18, '15–20 min', 'Group activity materials', 'Work on a group project (art, building, game). Contribute without needing to lead or control -- fellowship skill.', 'Friendships become genuinely important now, and the skills involved are learnable rather than automatic. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('care-something-living-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Care Something Living', 'A hands-on challenge that builds empathy and perspective-taking.', null, 'Ongoing', 'Plant and watering can', 'Water a plant daily for a week. Small, consistent caretaking responsibility builds empathy and agency together.', 'This builds emotional understanding and social confidence at the age when both start to matter outside home. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'CASEL Social-Emotional Framework; NAEYC Developmentally Appropriate Practice; IAP'),
  ('leaf-printing-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Leaf Printing', 'An activity that develops sensory art and texture tolerance.', 13, '10–15 min', 'Leaves, paint, paper', 'Press autumn leaves with paint onto paper. Vein detail prints clearly -- observe the structure of the leaf in the print.', 'This gives your child varied physical and sensory input, which supports concentration afterwards. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-instruments-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Make Instruments', 'A hands-on challenge that builds auditory discrimination.', 18, '15–20 min', 'Bottles, rice, rubber bands, boxes', 'Fill bottles with different amounts of rice for shakers, stretch rubber band across box for guitar. Sound science.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('room-torch-exploration-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Room Torch Exploration', 'A play-based activity for strengthening sensory discrimination and integration.', 13, '10–15 min', 'Torch', 'In a darkened room: explore what the torch illuminates. Experiment with angles, distance, colour.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('make-kite-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Make Kite', 'A play-based activity for strengthening sensory discrimination and integration.', 18, '15–20 min', 'Paper, sticks, string', 'Simple kite from paper, sticks, and string. Fly it -- observe how wind interacts with a surface.', 'Sensory experience supports attention and regulation, and children this age still need plenty of it. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('cooking-y4_0', 'cognitive'::domain, 'y4_0'::age_band, 'Cooking', 'An activity that develops sensory discrimination and integration.', 25, '20–30 min', 'Simple food items', 'With adult present, child independently makes a simple dish: boiled egg, toast, fruit salad.', 'Hands-on sensory work builds both discrimination and the vocabulary to describe what they notice. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('manage-pocket-money-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'Manage Pocket Money', 'A hands-on challenge that builds everyday independence.', null, 'Ongoing', 'Small amount of real money', 'Given a small amount per week. Track what was spent and saved. Money management from the first rupee.', 'Doing things for themselves builds the planning and sequencing skills that also support learning. Resist correcting too quickly; a child who works something out slowly understands it better than one who is told.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('first-aid-basics-y4_0', 'social_emotional'::domain, 'y4_0'::age_band, 'First Aid Basics', 'An activity that develops everyday independence.', 8, '5–10 min', 'Bandage, cold water', 'Learn: stop bleeding with pressure, run cold water on burns. Two specific first-aid responses a 4-year-old can perform.', 'Children this age are far more capable than they are usually allowed to be, and real responsibility builds real confidence. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'AOTA Activities of Daily Living; NAEYC Developmentally Appropriate Practice; IAP'),
  ('without-training-wheels-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Without Training Wheels', 'An activity that develops balance and postural control.', 18, '15–20 min', 'Bicycle without training wheels', 'Remove training wheels when balance bike balance is good. First real bike = one of the most complex motor achievements of childhood.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Focus on the effort rather than the outcome, which is what keeps children willing to attempt hard things.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP'),
  ('skip-rope-y4_3', 'motor'::domain, 'y4_3'::age_band, 'Skip Rope', 'An activity that develops jumping, hopping and skipping.', 13, '10–15 min', 'Jump rope', 'Turn own rope and jump: 10+ consecutive jumps. Coordinating arm circles and leg jumps is a high-level motor achievement.', 'At this age motor skills become more precise and more deliberate, and practice is what sharpens them. Let your child take the lead and follow their ideas, even when they are stranger than yours.', 'WHO Physical Activity Guidelines (5–17); AAP Physical Activity; IAP')
